def trivialize(ga, basepoint, y):
    return ga.conn(basepoint, y)

def untrivialize(ga, basepoint, g):
    return ga.act(g, basepoint)

def csidh_keygen(ga, x0):
    s = random.randint(0, ga.n-1)
    return (s, ga.act(s, x0))

def csidh_shared(ga, s, pk):
    return ga.act(s, pk)

def sigma_extract(ga, t0, t1):
    assert t0.commitment == t1.commitment
    return ga.multiply(t0.response, ga.inverse(t1.response))

def cayley_diameter(n, gens):
    dist = [-1]*n; dist[0] = 0; q = [0]; md = 0
    while q:
        v = q.pop(0)
        for s in gens:
            w = (v+s)%n
            if dist[w]==-1:
                dist[w] = dist[v]+1
                md = max(md, dist[w]); q.append(w)
    return md
